243	     */
244	    private static function makeKey(array $data, string $prefix = '', string $separator = ':'): string
245	    {
246	        $tmp = [];
247	        foreach ($data as $key => $value) {
248	            $tmp[] = $key . '=' . $value;
249	        }
250	        return $prefix . $separator . implode($separator, $tmp);
251	    }
