257	    public static function getLeftUntilMaxAmount(int $userId, ?int $userBonusId = null, ?int $gameId = null, ?int $freespinId = null, bool $useCache = true): ?float
258	    {
259	        if (!static::hasMaxWin(userId: $userId, userBonusId: $userBonusId, freespinId: $freespinId)) {
260	            return null;
261	        }
262	
263	        $where = array_filter([
264	            'user_id'       => $userId,
265	            'active'        => true,
266	            'finish'        => false,
267	            'user_bonus_id' => $userBonusId,
268	            'freespin_id'   => $freespinId,
269	            'game_id'       => $gameId,
270	        ], static fn($v) => $v !== null);
271	
272	        $ttl = ArrayHelper::getValue(Yii::$app->params, 'max_win.ttl', 6400);
273	        $key = self::makeKey($where, 'leftUntilMaxAmount');
274	
275	        $cached = Yii::$app->redis->get($key);
276	        if ($cached !== null && $useCache) {
277	            return $cached;
278	        }
279	        /** @var static|null $model */
280	        $model = static::find()->where($where)->one();
281	        Yii::$app->redis->setex($key, $ttl, $model?->left_until_max_amount); // на всякий случай, если в процессе удалили запись
282	        return $model?->left_until_max_amount;
283	    }
