151	        // «ФС не створились» до конкретного бонуса й гравця. А причина відмови майже завжди
152	        // у налаштуваннях саме бонуса: не та гра, не та валюта, вичерпаний ліміт.
153	        $logLabels = [
154	            'module' => 'freespin',
155	            'player_id' => $userUuid,
156	            'currency' => $currency,
157	            'game_uuid' => $gameUid,
158	            'bonus_id' => $bonusId,
159	            'bonus_type' => $bonus_type,
