162	        $gameModule = Yii::$app->getModule('game-search');
163	        $game = $gameModule->getGameBySlug(slug: $gameUid);
164	
165	        if(empty($game)){
166	            Logger::writeToLoki(
167	                'createFreeSpin: game not found for gameUid:' . $gameUid,
168	                'create_freespin',
169	                'error',
170	                $logLabels
171	            );
172	            Logger::writeError('createFreeSpin Game not found for gameUid:'.$gameUid
173	                . ' bonusId:' . var_export($bonusId, true) . ' userUuid:' . $userUuid);
174	            return false;
175	        }
176	
177	        // квота: Gaminator — будь-який ліміт у валюті (як було), AggregatorUA — ліміт ключа гри, EGT — без квоти
178	        // @infection-ignore-all тонкий адаптер: правило в FreespinQuotaPolicy::allows (тести AU-007), тут ранній вихід і логи, перевірка на стенді
179	        if (!self::quotaAllows($game, $currency)) {
