191	
192	        $model = new Freespin();
193	        $model->player_id = $userUuid;
194	        $model->currency = $currency;
195	        $model->denomination = $denomination;
196	        $model->quantity = $quantity;
197	        $model->game_uuid = $gameUid;
198	        $model->status = Freespin::STATUS_NEW;
199	        $model->bonus_id = $bonus_type == self::BONUS ? $bonusId : null;
200	        $model->bonus_type = $bonus_type;
201	        $model->bonus_cod_id = $bonus_type == self::BONUS_COD ? $bonusId: null;
