285	            Logger::writeInfo($tttext);
286	            Logger::writeToLoki($tttext, 'create_freespin', 'error', $logLabels);
287	
288	            // Recovery-логіка у catch має бути куленепробивною: refresh()/save() самі можуть
289	            // кинути виняток, і він вилетів би з методу замість return false.
