    public function isReadyToUse(): bool
    {
        if (!in_array($this->status, [self::STATUS_READY, self::STATUS_NEW, self::STATUS_USED])) return false;
        if ($this->valid_until < time()) return false;
        return true;
    }

    public function cancelFreespin(int $status = self::STATUS_CANCEL_ADMIN): bool
    {
        if (!in_array($this->status, [self::STATUS_READY, self::STATUS_USED])) {
            $this->addError(attribute: 'status',error: 'Forbidden cancel if status ready');
            return false;
        }

        // Провайдер-агностичне скасування. Адаптер логує деталі; тут піднімаємо
        // помилку, щоб адмінка (actionCancel) показала причину.
        if (!self::cancelByProvider($this)) {
            $this->addError('status', 'Provider rejected freespin cancel');
            return false;
        }

        $this->status = $status;
        $this->is_canceled = time();
        if (!$this->save()) {
            return false;
        }
        if ($this->userBonus) {
            $this->userBonus->closeBonus();
        } else {
            $this->bonusCodLog?->closeBonus();
        }
        if ($this->maxWinUserBonus) {
            $this->maxWinUserBonus->cancelMaxWin();
        }
        return true;
    }

    /**
     * Скасувати кампанію у провайдера БЕЗ зміни статусу/бонусів у нас.
     * Заміна розкиданих `new Gaminator(...)->freespinCancel(...)`: викликає
     * адаптер провайдера, який інкапсулює перевірку відповіді ('Canceled'/HTTP 200)
     * та логування/flash. Повертає true, якщо кампанію скасовано у провайдера.
     */
    public static function cancelByProvider(Freespin $freespin): bool
    {
        return self::resolveProvider($freespin->game)->cancelCampaign($freespin);
    }

    /**
     * @go-parity internal/models/freespin.go IsEnded
     *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
     */
    public function isEnded($gameActionTime = null)
    {
        // $gameActionTime = 16:13 , $this->updated_at = 16:15, now = 16:15 or 16:16
        if ($gameActionTime && $gameActionTime < $this->updated_at) {
            // значить перевірка по ігровій сесії , коли фс ще не були завершені
            return false;
        }
        return $this->status == Freespin::STATUS_END || $this->quantity_left === 0 || $this->quantity_left == '0';
    }
}

