35	class BackgroundGameProcess
36	{
37	    /**
38	     * @go-parity маршрутизація users_for_go_worker → черга slotor_game_go (config RABBITMQ_QUEUE_NAME)
39	     *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
40	     */
41	    public static function runQueue(array $gameAction, User $user): void
42	    {
43	        try {
44	            if (isset(Yii::$app->params['users_for_go_worker']) && (in_array('*',Yii::$app->params['users_for_go_worker']) || in_array($user->id,Yii::$app->params['users_for_go_worker']))) {
45	                Yii::$app->queueGameGo->push(new \common\jobs\GameProcess(['game_action' => $gameAction]));
46	                if (!YII_ENV_PROD) Logger::writeInfo(__METHOD__ . '::' . 'Run GO Queue');
47	            }else{
48	                Yii::$app->queueGame->push(new \common\jobs\GameProcess(['game_action' => $gameAction]));
49	                if (!YII_ENV_PROD) Logger::writeInfo(__METHOD__ . '::' . 'Run PHP Queue');
50	            }
51	        } catch (\Exception $ex) {
52	            BackgroundGameProcess::processingGameTransaction($gameAction);
53	            if (!YII_ENV_PROD) Logger::writeInfo(__METHOD__ . '::' . 'Run NOW');
54	        }
55	    }
56	
57	    /**
58	     * @go-parity internal/processor/freespin.go syncMaxWinCache
59	     *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
60	     */
61	    private static function updateMaxWin(UserBonus|Freespin $model): void
62	    {
63	        $mutex = new RedisMutex(['redis' => Yii::$app->redis, 'expireTime' => 2]);
64	        $key = __CLASS__ . '_max_win' . $model->id;
65	        try {
66	            if ($mutex->acquire($key)) {
67	                $model->maxWinUserBonus->refresh();
68	                MaxWinUserBonus::syncLeftUntilMaxAmountCache(
69	                    userId: $model->getUserId(),
70	                    userBonusId: ($model instanceof UserBonus) ? $model->id : null,
71	                    gameId: ($model instanceof Freespin) ? $model->game->id : null,
72	                    freespinId: ($model instanceof Freespin) ? $model->id : null,
73	                );
74	                $mutex->release($key);
75	            } else {
76	                usleep(1_000_000 * 0.05);
77	                self::updateMaxWin($model);
78	            }
79	        } catch (\Throwable $e) {
80	            $mutex->release($key);
81	            Logger::writeError("BackgroundGameProcess::updateMaxWin[{$model->id}]:" . $e->getMessage() . PHP_EOL . $e->getTraceAsString());
82	        }
83	    }
84	
