86	     * @go-parity internal/processor/game_processor.go processGameAction, processBet; internal/processor/freespin.go processFreespin
87	     *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
88	     */
89	    public static function processingGameTransaction($game_action)
90	    {
91	        $game = Game::find()->where(['slug'=>$game_action['game_uuid']])->one();
92	        $user = User::find()->where(['uid' => $game_action['player_id']])->one();
93	
94	        if(empty($game) ){
95	            return true;
96	        }
97	
98	        if (!YII_ENV_PROD){
99	            Logger::writeToLoki(json_encode([
100	                    'userId' => $user ? $user->id : null,
101	                    'gameId' => $game->id,
102	                    'data' => $game_action,
103	                ]),'__TEST__GR_CALLBACK');
104	        }
105	
106	        if($game_action['type'] === 'freespin'){
107	            if (!isset($game_action['freespin_id'])){
108	                Logger::writeInfo('processingGameTransaction freespin_id empty: SessionId:'.$game_action['session_id']);
109	                return false;
110	            }
111	
112	            /** @var Freespin $freespin */
113	            $freespin = Freespin::find()->where(['freespin_id' => $game_action['freespin_id']])->one();
114	            if (!$freespin) {
115	                Logger::writeInfo('processingGameTransaction Freespin not found: SessionId:'.$game_action['session_id']);
116	                return false;
117	            }
118	            /** @var UserBonus $userBonus */
119	            $userBonus = $freespin->userBonus;
120	
121	            if (!$userBonus) {
122	                if ($freespin->hasMaxWin()) {
123	                    self::updateMaxWin($freespin);
124	                    $transaction = Yii::$app->db->beginTransaction();
125	                    $wallet = Wallet::find()->where(['user_id'=>$user->id,'currency'=>$game_action['currency']])->one();
126	                    try {
127	                        $amount = $game_action['amount'];
128	                        if (!YII_ENV_PROD) Logger::writeInfo("__TEST__GR_CALLBACK [" . __LINE__ . "]:" . json_encode(['amount' => $amount]));
129	                        $amount = $freespin->maxWinUserBonus->getAllowedAmountToDep($amount);
130	                        if (!YII_ENV_PROD) Logger::writeInfo("__TEST__GR_CALLBACK [" . __LINE__ . "]:" . json_encode(['amount' => $amount]));
131	                        $wallet->deposit($amount);
132	                        $transaction->commit();
133	                    } catch (Exception $ex) {
134	                        $transaction->rollBack();
135	                        Logger::writeError('Bonus confirm error: user_bonusId:'.$userBonus->id .' userId:'.$userBonus->user_id .' CAUSE: '.$ex->getMessage());
136	                        throw $ex;
137	                    }
138	                }
139	                //якщо нема бонусу , то це може бути промокод просто з фс, без вейджеру - вони в іншій таблиці зберігаються
140	                $promocod = $freespin->bonusCodLog;
141	                if ($promocod && ($freespin->isEnded())) {
142	                    $promocod->used = true;
143	                    $promocod->save();
144	                }
145	                return true;
146	            }
147	
148	            if(!$userBonus->isActive() || $userBonus->status == \common\models\UserBonus::STATUS_END || $userBonus->status == \common\models\UserBonus::STATUS_REFUSE){
149	                return false;
150	            }
151	
152	            if($game_action['action'] === 'win'){
153	                $amount = $game_action['amount'];
154	//                $amount = ($userBonus->maxWinUserBonus) ? $userBonus->maxWinUserBonus->getAllowedAmountToDep($amount) : $amount;
155	
156	                if($userBonus->is_wager){
157	                    //По ТЗ Если это бонус ФС вейджерный относительный(процентный) то вейджер начисляем динамически от выигрыша
158	                    $addAmount = $amount;
159	                    if ($userBonus->hasMaxWin()) {
160	                        $maxWinBonus = $userBonus->maxWinUserBonus;
161	                        $addAmount = $maxWinBonus ? $maxWinBonus->getAllowedAmountToDep($amount) : $amount;
162	                    }
163	                    if($userBonus->wagerTypePercent()){
164	                        //вейджер може бути меншим від виграшу по максвін
165	                        $wagerSum = $addAmount * $userBonus->amount_percent_wager/100;
166	                        $userBonus->wager = $userBonus->wager + $wagerSum;
167	                        $userBonus->amount_wager = $userBonus->amount_wager + $wagerSum;
168	                    }
