/**
 * пошук останнього ФС по грі та гравцю . Скасування ФС
 * @param $freespin
 * @return bool
 * @throws Exception
 * @throws \yii\db\Exception
 */
public function cancelLasFs($freespin)
{
    $lastFs = Freespin::find()->where([
        'player_id' => $freespin->player_id,
        'game_uuid' => $freespin->game_uuid,
    ])->andWhere(['<>', 'freespin_id', $freespin->freespin_id])
        ->orderBy(['id' => SORT_DESC])->one();
    if ($lastFs) {
        $resultCancel = $this->freespinCancel($lastFs->freespin_id);
        if (isset($resultCancel['status']) && $resultCancel['status'] == 'Canceled') {
            $lastFs->status = Freespin::STATUS_CANCEL_AUTO;
            $lastFs->is_canceled = time();
            $transaction = Yii::$app->db->beginTransaction();
            try {
                if (!$lastFs->save()) {
                    $transaction->rollBack();
                    return false;
                }
                if ($lastFs->userBonus) {
                    $lastFs->userBonus->closeBonus();
                } else {
                    $lastFs->bonusCodLog?->closeBonus();
                }
                $lastFs->maxWinUserBonus?->cancelMaxWin();
                $transaction->commit();
            } catch (\Throwable $e) {
                $transaction->rollBack();
                throw $e;
            }
            return true;
        } else {
            $hed = ' Headers: ' . \yii\helpers\VarDumper::dumpAsString($this->requestHeaders, 30, false);
            $textErr = 'Error Cancel freespin_id:' . $lastFs->freespin_id . ';   Currency:' . $lastFs->currency . ' =====';
            $log = \yii\helpers\VarDumper::dumpAsString($resultCancel, 30, false);
            Logger::writeError($textErr . $log . $hed);
        }
    }
    return false;

