/**
 * Whether a gift-spin win is credited to the REAL balance synchronously (plain
 * freespin) vs routed to bonus money (wager / max-win) — the SiteController
 * freespin-win predicate. Deterministic from the freespin's bonus config, so
 * the idempotency replay reconstructs the same real/bonus split.
 */
private function giftSpinCreditsReal(Freespin $freespin): bool
{
    $userBonus = $freespin->userBonus;
    $hasMaxWin = ($userBonus && $userBonus->hasMaxWin()) || (!$userBonus && $freespin->hasMaxWin());
    $isWager   = $userBonus && $userBonus->is_wager;

    return !($isWager || $hasMaxWin);
}

/**
 * Reproduce the ORIGINAL deposit response for an idempotent retry (§4.7: the
 * operator must respond with the same response). A gift-spin win may have split
 * the amount into real/bonus (wager / max-win), so the replay reconstructs that
 * same split from the freespin instead of blindly reporting the whole amount as
 * real. Non-gift-spin — and a gift-spin whose freespin is not found, which
 * originally fell through to a full real credit — replay the full realAmount.
 */
private function replayDepositResponse(array $data, string $reason, User $user, Wallet $wallet, string $transferId, int $rawAmountCoins): array
{
    if ($reason === 'GIFT_SPIN') {
        $freespin = $this->findGiftSpin($data, $user, $wallet->currency);
        if ($freespin) {
            $split = EgtWallet::giftSpinSplit($this->giftSpinCreditsReal($freespin), $rawAmountCoins);
            return $this->signedTransferResponse($wallet, $transferId, $split['real'], $split['bonus']);
        }
    }

    return $this->signedTransferResponse($wallet, $transferId, $rawAmountCoins);
}

