7	/**
8	 * Боевой шлюз {@see RewardIssueService} для одного выданного бонуса: ФС — через
9	 * `Freespin::createFreeSpin` и отмену у провайдера, зачисление — транзакцией, которую
10	 * передаёт контроллер активации (design, решение 4: маршрутизация и ответ — свои у сайта и API).
11	 *
12	 * @infection-ignore-all тонкий адаптер к провайдеру ФС и БД без собственных правил, в common/unit их нет
13	 * @codeCoverageIgnore
14	 */
15	final class FreespinRewardIssueGateway implements RewardIssueGateway
16	{
17	    /**
18	     * @param \Closure(DepositReward, ?string): void $credit транзакция зачисления; при ошибке откатывается и бросает
19	     */
20	    public function __construct(
21	        private readonly string $playerUid,
22	        private readonly string $currency,
