48	    /**
49	     * Как откат в текущей активации: отмена у провайдера и статус «отменено автоматически».
50	     */
51	    public function cancelFreespins(string $freespinId): bool
52	    {
53	        $freespin = Freespin::find()->where(['freespin_id' => $freespinId])->one();
54	        if ($freespin === null || !Freespin::cancelByProvider($freespin)) {
55	            return false;
56	        }
57	        $freespin->status = Freespin::STATUS_CANCEL_AUTO;
58	        $freespin->is_canceled = time();
59	        return $freespin->save(false);
60	    }
61	
62	    public function credit(DepositReward $reward, ?string $freespinId): void
63	    {
64	        ($this->credit)($reward, $freespinId);
65	    }
